const canvas=document.getElementById('bodyCanvas'),ctx=canvas.getContext('2d');
let layers={skin:false,muscle:true,vascular:true,organs:true,cells:false}, view='systems', playing=false, seconds=0, speed=1, ingredients=[];
function resize(){const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;canvas.width=r.width*d;canvas.height=r.height*d;ctx.setTransform(d,0,0,d,0,0)}
window.addEventListener('resize',resize); resize();
function line(points,color,w=1,alpha=1){ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle=color;ctx.lineWidth=w;ctx.lineJoin='round';ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.stroke();ctx.restore()}
function draw(){const w=canvas.clientWidth,h=canvas.clientHeight,cx=w/2,sc=Math.min(w/440,h/600), top=28;ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(cx,top);ctx.scale(sc,sc);const pulse=1+Math.sin(seconds*4)*.025;
 // halo and ground
 ctx.beginPath();ctx.ellipse(0,580,105,14,0,0,Math.PI*2);ctx.fillStyle='#153940';ctx.fill();ctx.strokeStyle='#306168';ctx.stroke();
 ctx.beginPath();ctx.arc(0,52,43,0,Math.PI*2);ctx.fillStyle=layers.skin?'#b97269':'#142c32';ctx.globalAlpha=layers.skin?.9:.28;ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=layers.skin?'#e09583':'#54878b';ctx.lineWidth=1.3;ctx.stroke();
 // neck and trunk silhouette
 ctx.beginPath();ctx.moveTo(-19,91);ctx.lineTo(-22,112);ctx.lineTo(-72,127);ctx.lineTo(-80,259);ctx.lineTo(-54,325);ctx.lineTo(-43,425);ctx.lineTo(-25,425);ctx.lineTo(0,405);ctx.lineTo(25,425);ctx.lineTo(43,425);ctx.lineTo(54,325);ctx.lineTo(80,259);ctx.lineTo(72,127);ctx.lineTo(19,112);ctx.closePath();ctx.fillStyle=layers.skin?'#a95f5d':'#142f35';ctx.globalAlpha=layers.skin?.9:.2;ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=layers.muscle?'#e27676':'#527e83';ctx.lineWidth=1.5;ctx.stroke();
 // arms and legs
 const limbs=[[-69,130,-113,270,-108,406,-99,566], [69,130,113,270,108,406,99,566],[-42,410,-48,470,-52,566], [42,410,48,470,52,566]];limbs.forEach((p,i)=>{line([[p[0],p[1]],[p[2],p[3]],[p[4],p[5]],[p[6],p[7]]],layers.skin?'#a95f5d':'#557a7e',layers.skin?18:12,.85);line([[p[0],p[1]],[p[2],p[3]],[p[4],p[5]],[p[6],p[7]]],layers.muscle?'#d85e69':'#4d7b80',layers.skin?8:5,.9)});
 // muscles segmented
 if(layers.muscle){ctx.globalAlpha=.72;ctx.fillStyle='#c95462';[['#b95a68',-43,150,34,74],['#bc5865',9,150,34,74],['#d26b70',-38,244,30,65],['#d26b70',8,244,30,65],['#b95b6a',-32,334,25,74],['#b95b6a',7,334,25,74]].forEach(a=>{ctx.fillStyle=a[0];ctx.beginPath();ctx.ellipse(a[1],a[2],a[3]/2,a[4]/2,0,0,Math.PI*2);ctx.fill()});ctx.globalAlpha=1}
 // vascular network
 if(layers.vascular){const red='#e45b68',blue='#55c6e1';line([[0,132],[0,401]],red,2,.8);line([[0,160],[-35,205],[-50,275],[-78,360],[-102,480]],red,1.3,.8);line([[0,160],[35,205],[50,275],[78,360],[102,480]],red,1.3,.8);line([[0,184],[-48,158],[-88,226],[-105,340]],blue,1.5,.8);line([[0,184],[48,158],[88,226],[105,340]],blue,1.5,.8);line([[-35,205],[-18,286],[-22,390]],blue,1,.65);line([[35,205],[18,286],[22,390]],blue,1,.65);for(let i=0;i<10;i++){let y=170+i*33;ctx.fillStyle=i%2?red:blue;ctx.beginPath();ctx.arc(Math.sin(i)*28,y,2,0,7);ctx.fill()}}
 // organs
 if(layers.organs){ctx.globalAlpha=.9;ctx.fillStyle='#b84f68';ctx.beginPath();ctx.arc(-17,197,17*pulse,0,7);ctx.fill();ctx.fillStyle='#b85c73';ctx.beginPath();ctx.arc(17,197,17*pulse,0,7);ctx.fill();ctx.fillStyle='#c75b62';ctx.beginPath();ctx.ellipse(10,257,31,21,.1,0,7);ctx.fill();ctx.fillStyle='#d27a55';ctx.beginPath();ctx.ellipse(-10,292,39,23,-.12,0,7);ctx.fill();ctx.fillStyle='#84577e';ctx.beginPath();ctx.ellipse(0,345,27,17,0,0,7);ctx.fill();ctx.globalAlpha=1;line([[-18,179],[-18,216]],'#ff8e86',1,.6);line([[18,179],[18,216]],'#ff8e86',1,.6)}
 // cells
 if(layers.cells){for(let i=0;i<30;i++){let x=Math.sin(i*8.2+seconds*.7)*85,y=145+(i*47)%350;ctx.fillStyle=i%3?'#ed7280':'#70d6df';ctx.globalAlpha=.8;ctx.beginPath();ctx.arc(x,y,2+(i%3),0,7);ctx.fill()}ctx.globalAlpha=1}
 if(view==='xray'){ctx.globalAlpha=.7;for(let i=0;i<11;i++)line([[-30+i*6,110],[-32+i*6,409]],'#9be8ed',1,.5);line([[0,90],[0,410]],'#c4f6ed',2,.7);ctx.globalAlpha=1}ctx.restore();requestAnimationFrame(draw)}requestAnimationFrame(draw);

document.querySelectorAll('[data-layer]').forEach(x=>x.addEventListener('change',e=>{layers[e.target.dataset.layer]=e.target.checked}));document.getElementById('resetLayers').onclick=()=>{document.querySelectorAll('[data-layer]').forEach(x=>{x.checked=['muscle','vascular','organs'].includes(x.dataset.layer);layers[x.dataset.layer]=x.checked})};
document.querySelectorAll('.tool').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tool').forEach(x=>x.classList.remove('active'));b.classList.add('active');view=b.dataset.view;document.getElementById('viewMode').textContent=view.toUpperCase()});
function updateTime(){seconds+=speed;let s=seconds%60,m=Math.floor(seconds/60)%60,h=Math.floor(seconds/3600),pad=n=>String(n).padStart(2,'0');document.getElementById('timeValue').textContent=`${pad(h)}:${pad(m)}:${pad(s)}`;document.getElementById('timelineFill').style.width=`${Math.min(90,23+seconds/4)}%`;document.getElementById('timelineKnob').style.left=`${Math.min(90,23+seconds/4)}%`;if(seconds%6===0){document.getElementById('heartRate').textContent=72+Math.round(Math.sin(seconds)*3)}}
document.getElementById('playBtn').onclick=()=>{playing=!playing;document.getElementById('playBtn').textContent=playing?'Ⅱ':'▶';if(playing){window.timer=setInterval(updateTime,1000)}};document.querySelectorAll('.speed').forEach(b=>b.onclick=()=>{document.querySelectorAll('.speed').forEach(x=>x.classList.remove('active'));b.classList.add('active');speed=+b.textContent[0]});
function renderSlots(){const s=document.getElementById('slots');s.innerHTML='';ingredients.forEach(i=>{let d=document.createElement('div');d.className='filled-slot';d.style.borderColor=i.color;d.innerHTML=`<span style="color:${i.color}">✦</span><small>${i.name.slice(0,7).toUpperCase()}</small>`;s.appendChild(d)});for(let i=ingredients.length;i<3;i++){let d=document.createElement('div');d.className='empty-slot '+(i?'locked':'');d.innerHTML=i?'＋':'+<span>ADD COMPOUND</span>';s.appendChild(d)}document.getElementById('ingredientCount').textContent=`${ingredients.length} / 3`;let ready=ingredients.length>0;document.getElementById('injectBtn').disabled=!ready;document.getElementById('formulaState').textContent=ready?'READY':'EMPTY';document.getElementById('formulaState').style.color=ready?'#57e0b0':'#e2a650';document.getElementById('formulaName').textContent=ready?ingredients.map(x=>x.name).join(' + '):'No compound selected';document.getElementById('formulaBar').style.width=(ingredients.length/3*100)+'%';document.getElementById('formulaHint').textContent=ready?'Compound balanced · ready for controlled injection.':'Select ingredients to begin a formulation.'}
document.querySelectorAll('.compound').forEach(b=>b.onclick=()=>{if(ingredients.length<3){ingredients.push({name:b.dataset.name,color:b.dataset.color});renderSlots();}});document.getElementById('clearBtn').onclick=()=>{ingredients=[];renderSlots()};document.getElementById('injectBtn').onclick=()=>{const t=document.getElementById('toast');t.textContent='INJECTION LOGGED · monitoring physiological response';t.classList.add('show');layers.cells=true;document.querySelector('[data-layer="cells"]').checked=true;setTimeout(()=>t.classList.remove('show'),2800);};renderSlots();

